/* VietinBank KPI — generated from tokens.json */
:root, [data-theme="light"] {
  --brand-blue: #005993;
  --brand-blue-dark: #004573;
  --brand-blue-tint: #e6f1f8;
  --brand-red: #d71249;
  --surface-page: #f4f6fa;
  --surface-card: #ffffff;
  --surface-sunken: #eaeff6;
  --line: #e3e9f2;
  --line-strong: #8693a9;
  --ink: #15233b;
  --ink-2: #4a5a72;
  --ink-muted: #5a6881;
  --on-brand: #ffffff;
  --focus-ring: var(--brand-blue);
  --tier-dat: #1c5cab;
  --tier-dat-tint: #e4ebf5;
  --tier-dat-ink: #1c5cab;
  --on-tier-dat: #ffffff;
  --tier-kha: #6da7ec;
  --tier-kha-tint: #edf4fd;
  --tier-kha-ink: #1b6dce;
  --on-tier-kha: #15233b;
  --tier-cct: #ec835a;
  --tier-cct-tint: #fdf0eb;
  --tier-cct-ink: #c04616;
  --on-tier-cct: #15233b;
  --tier-chua: #b02a2a;
  --tier-chua-tint: #f6e5e5;
  --tier-chua-ink: #b02a2a;
  --on-tier-chua: #ffffff;
  --tier-gap: #8996ab;
  --tier-gap-tint: #f1f2f5;
  --tier-gap-ink: #606f87;
  --on-tier-gap: #15233b;
  --series-1: #005993;
  --series-2: #eb6834;
  --series-3: #1baf7a;
  --series-4: #6250d6;
  --series-neutral: var(--line-strong);
  --seq-100: #cde2fb;
  --seq-250: #86b6ef;
  --seq-400: #3987e5;
  --seq-550: #1c5cab;
  --seq-700: #0d366b;
  --chart-grid: #e3e9f2;
  --chart-axis: #b9c3d3;
  --chart-ref: var(--ink-2);
  --forecast: var(--brand-blue);
  --delta-up: var(--tier-dat-ink);
  --delta-down: var(--tier-chua-ink);
  --shadow-card: 0 1px 2px rgba(16, 38, 77, 0.06);
  --shadow-pop: 0 8px 24px rgba(16, 38, 77, 0.16);
}
:root {
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-6: 24px;
  --space-8: 32px;
  --space-12: 48px;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-pill: 999px;
  --layout-max: 1600px;
  --stage-w: 1920px;
  --stage-h: 1080px;
  --tap-min: 32px;
  --font-sans: "Plus Jakarta Sans", "Segoe UI", system-ui, sans-serif;
}
.caption { font-family: var(--font-sans); font-size: 12px; line-height: 16px; font-weight: 500; }
.label { font-family: var(--font-sans); font-size: 12px; line-height: 16px; font-weight: 600; letter-spacing: 0.01em; }
.body { font-family: var(--font-sans); font-size: 14px; line-height: 20px; font-weight: 400; }
.title-sm { font-family: var(--font-sans); font-size: 16px; line-height: 22px; font-weight: 600; }
.title { font-family: var(--font-sans); font-size: 20px; line-height: 28px; font-weight: 600; }
.display { font-family: var(--font-sans); font-size: 28px; line-height: 34px; font-weight: 700; }
.hero { font-family: var(--font-sans); font-size: 52px; line-height: 56px; font-weight: 700; }
.present-caption { font-family: var(--font-sans); font-size: 16px; line-height: 22px; font-weight: 500; }
.present-body { font-family: var(--font-sans); font-size: 20px; line-height: 28px; font-weight: 500; }
.present-title { font-family: var(--font-sans); font-size: 26px; line-height: 34px; font-weight: 600; }
.present-display { font-family: var(--font-sans); font-size: 40px; line-height: 46px; font-weight: 700; }
.present-hero { font-family: var(--font-sans); font-size: 96px; line-height: 100px; font-weight: 700; }
